REJECT_THRESHOLD = 0.35
REVIEW_UPPER = 0.55


def decide(score: float) -> Outcome:
    if score < REJECT_THRESHOLD:
        # auto-reject: email is sent by notifications worker
        return Outcome.REJECT
    if score < REVIEW_UPPER:
        return Outcome.MANUAL_REVIEW
    return Outcome.SHORTLIST

def extract_text(upload: UploadFile) -> str:
    if upload.content_type not in ALLOWED_TYPES:
        raise UnsupportedFile(upload.content_type)
    raw = upload.file.read(MAX_BYTES + 1)
    if len(raw) > MAX_BYTES:
        raise FileTooLarge()
    text = _to_text(raw, upload.content_type)
    # strip zero-width / hidden characters used to game keyword matching
    text = HIDDEN_CHARS.sub("", text)
    return text

resource "aws_s3_bucket_server_side_encryption_configuration" "raw_cvs" {
  bucket = aws_s3_bucket.raw_cvs.id
  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm     = "aws:kms"
      kms_master_key_id = aws_kms_key.data.arn
    }
  }
}
